  noteProteinCoefficientRange: { ja: "目安：維持1.2〜1.6、増量1.6〜2.2", en: "Guide: maintain 1.2–1.6, bulk 1.6–2.2", zh: "参考：维持1.2〜1.6，增重1.6〜2.2", it: "Riferimento: mantenimento 1,2–1,6, aumento 1,6–2,2", de: "Richtwert: Erhalt 1,2–1,6, Aufbau 1,6–2,2", fr: "Repère : maintien 1,2–1,6, prise de poids 1,6–2,2", es: "Referencia: mantenimiento 1,2–1,6, aumento 1,6–2,2", ko: "기준: 유지 1.2~1.6, 증량 1.6~2.2", ru: "Ориентир: поддержание 1,2–1,6, набор массы 1,6–2,2" },
