  noteAnalysisPeriodCount: { ja: "選んだ期間内の記録: {count}日分", en: "Records in this period: {count} days", zh: "所选期间内的记录：{count}天", it: "Registrazioni in questo periodo: {count} giorni", de: "Aufzeichnungen in diesem Zeitraum: {count} Tage", fr: "Enregistrements sur cette période : {count} jours", es: "Registros en este período: {count} días", ko: "선택한 기간의 기록: {count}일", ru: "Записей за выбранный период: {count} дн." },
  titleTimeOfDayTrend: { ja: "時間帯別の声の傾向", en: "Voice trends by time of day", zh: "各时段的声音趋势", it: "Andamento della voce per fascia oraria", de: "Stimmtrends nach Tageszeit", fr: "Tendances vocales par période", es: "Tendencias de la voz por franja horaria", ko: "시간대별 목소리 경향", ru: "Динамика голоса по времени суток" },
  noteTimeOfDayTrend: { ja: "「時間帯別に記録」した内容の平均値です。件数が少ないうちは参考程度にご覧ください。", en: "Averages from your \"record by time of day\" entries. Treat as a rough guide until you have more data.", zh: "这是「按时段记录」内容的平均值。记录数较少时仅供参考。", it: "Medie dei dati inseriti in \"registrazione per fascia oraria\". Considerali indicativi finché non hai più dati.", de: "Durchschnittswerte aus deinen Einträgen \"nach Tageszeit erfassen\". Bei wenigen Einträgen nur als grobe Orientierung.", fr: "Moyennes des saisies « par période de la journée ». À considérer comme indicatif tant que les données sont peu nombreuses.", es: "Promedios de tus entradas \"por franja horaria\". Tómalo como orientativo mientras tengas pocos datos.", ko: "'시간대별 기록'의 평균값입니다. 기록 수가 적을 때는 참고 정도로만 봐주세요.", ru: "Средние значения по записям «по времени суток». Пока данных мало, воспринимайте это как ориентир." },
  labelGoodTrend: { ja: "調子が良い傾向", en: "Tends to be better", zh: "状态较好的倾向", it: "Tendenza migliore", de: "Tendenziell besser", fr: "Tendance favorable", es: "Tiende a ser mejor", ko: "컨디션이 좋은 경향", ru: "Обычно лучше" },
  titleVoiceMemoReview: { ja: "声のメモ振り返り", en: "Voice memo review", zh: "声音笔记回顾", it: "Rassegna delle note sulla voce", de: "Rückblick auf Stimmnotizen", fr: "Relecture des notes vocales", es: "Repaso de notas de voz", ko: "목소리 메모 돌아보기", ru: "Обзор заметок о голосе" },
  noteVoiceMemoReview: { ja: "「声・喉」の一口メモを書いた日の一覧です（直近10件）。その日の状態とあわせて見返せます。", en: "Days you wrote a quick note under \"Voice & Throat\" (last 10). Reviewable alongside that day's condition.", zh: "这里列出了写过「嗓音与喉咙」简短备注的日期（最近10条），可与当日状态一并回顾。", it: "Elenco dei giorni in cui hai scritto una nota rapida in \"Voce e gola\" (ultimi 10). Consultabile insieme alla condizione di quel giorno.", de: "Tage, an denen du eine Kurznotiz unter \"Stimme & Hals\" geschrieben hast (letzte 10). Zusammen mit dem Zustand des jeweiligen Tages einsehbar.", fr: "Jours où vous avez écrit une note rapide sous « Voix et gorge » (10 derniers). Consultable avec l'état du jour.", es: "Días en los que escribiste una nota rápida en \"Voz y garganta\" (últimos 10). Puedes revisarlos junto con el estado de ese día.", ko: "'목소리·목'에 짧은 메모를 남긴 날의 목록입니다(최근 10건). 그날의 상태와 함께 돌아볼 수 있습니다.", ru: "Список дней, когда была написана краткая заметка в разделе «Голос и горло» (последние 10). Можно просматривать вместе с состоянием за этот день." },
  titleRestMethodTrend: { ja: "休養方法ごとの声・メンタルの傾向", en: "Voice & mental trends by rest method", zh: "各休养方法下的声音与心理趋势", it: "Andamento vocale e mentale per metodo di riposo", de: "Stimm- und mentale Trends nach Erholungsmethode", fr: "Tendances vocales et mentales par méthode de repos", es: "Tendencias de voz y mente por método de descanso", ko: "휴양 방법별 목소리・멘탈 경향", ru: "Динамика голоса и настроения по способам отдыха" },
  noteRestMethodTrend: { ja: "「休養」の日に選んだ方法別の平均値です（件数が少ないうちは参考程度に）。", en: "Averages by method chosen on \"Rest\" days (treat as a rough guide with few entries).", zh: "这是「休息」当天所选方法的平均值（记录数较少时仅供参考）。", it: "Medie per metodo scelto nei giorni di \"Riposo\" (indicative con pochi dati).", de: "Durchschnittswerte je gewählter Methode an \"Erholungs\"-Tagen (bei wenigen Einträgen nur als Richtwert).", fr: "Moyennes par méthode choisie les jours de « Repos » (indicatif avec peu de données).", es: "Promedios por método elegido en los días de \"Descanso\" (orientativo con pocos datos).", ko: "'휴양'일에 선택한 방법별 평균값입니다(기록이 적을 때는 참고 정도로).", ru: "Средние значения по выбранным способам в дни «Отдыха» (при малом числе записей — лишь ориентир)." },
  titleLocationTrend: { ja: "滞在地ごとの声・メンタルの傾向", en: "Voice & mental trends by location", zh: "各所在地的声音与心理趋势", it: "Andamento vocale e mentale per località", de: "Stimm- und mentale Trends nach Aufenthaltsort", fr: "Tendances vocales et mentales par lieu", es: "Tendencias de voz y mente por ubicación", ko: "체류지별 목소리・멘탈 경향", ru: "Динамика голоса и настроения по месту пребывания" },
  noteLocationTrend: { ja: "2件以上記録のある滞在地のみ表示しています。", en: "Only locations with 2 or more records are shown.", zh: "仅显示有2条及以上记录的所在地。", it: "Vengono mostrate solo le località con 2 o più registrazioni.", de: "Es werden nur Orte mit 2 oder mehr Einträgen angezeigt.", fr: "Seuls les lieux avec 2 enregistrements ou plus sont affichés.", es: "Solo se muestran las ubicaciones con 2 o más registros.", ko: "2건 이상 기록이 있는 체류지만 표시합니다.", ru: "Показаны только места с 2 и более записями." },
