  labelMentalEase: { ja: "心の余裕", en: "Peace of mind", zh: "心理余裕", it: "Serenità", de: "Innere Ruhe", fr: "Sérénité", es: "Tranquilidad", ko: "마음의 여유", ru: "Душевное спокойствие" },
  lowTension: { ja: "緊張", en: "Tense", zh: "紧张", it: "Teso", de: "Angespannt", fr: "Tendu", es: "Tenso", ko: "긴장", ru: "Напряжение" },
  highCalm: { ja: "穏やか", en: "Calm", zh: "平静", it: "Calmo", de: "Ruhig", fr: "Calme", es: "Tranquilo", ko: "평온", ru: "Спокойствие" },
  noteRehearsalHint: { ja: "このページ上部「声・喉」の評価と、下部「メンタル」の評価に、リハーサルでの客観的な声・メンタルの状態を記録してください。", en: "Use the \"Voice & Throat\" section above and the \"Mental State\" section below to record your objective voice and mental state during the rehearsal.", zh: "请在本页上方的「嗓音与喉咙」评价和下方的「心理状态」评价中，记录彩排时客观的嗓音与心理状态。", it: "Usa la sezione \"Voce e gola\" sopra e la sezione \"Stato mentale\" sotto per registrare lo stato vocale e mentale oggettivo durante la prova.", de: "Nutze den Abschnitt \"Stimme & Hals\" oben und \"Mentaler Zustand\" unten, um deinen objektiven Stimm- und mentalen Zustand während der Probe festzuhalten.", fr: "Utilisez la section « Voix et gorge » ci-dessus et « État mental » ci-dessous pour noter votre état vocal et mental objectif pendant la répétition.", es: "Usa la sección \"Voz y garganta\" arriba y \"Estado mental\" abajo para registrar tu estado vocal y mental objetivo durante el ensayo.", ko: "이 페이지 위쪽의 '목소리·목' 평가와 아래쪽의 '멘탈' 평가에, 리허설 중 객관적인 목소리・멘탈 상태를 기록해 주세요.", ru: "Запишите объективное состояние голоса и настроения во время репетиции в разделе «Голос и горло» вверху страницы и в разделе «Ментальное состояние» внизу." },
  errorUnknown: { ja: "不明なエラー", en: "Unknown error", zh: "未知错误", it: "Errore sconosciuto", de: "Unbekannter Fehler", fr: "Erreur inconnue", es: "Error desconocido", ko: "알 수 없는 오류", ru: "Неизвестная ошибка" },

  placeholderVoiceMemoQuick: { ja: "声について気づいたことを一言", en: "A quick note about your voice", zh: "关于嗓音的简短记录", it: "Una breve nota sulla voce", de: "Eine kurze Notiz zu deiner Stimme", fr: "Une brève note sur votre voix", es: "Una breve nota sobre tu voz", ko: "목소리에 대해 느낀 점을 한마디로", ru: "Короткая заметка о вашем голосе" },
  placeholderMealNotesExample: { ja: "例：消化に良いものを中心に、公演前は控えめに", en: "e.g. mostly easy-to-digest foods; lighter meals before performances", zh: "例：以易消化的食物为主，演出前减量", it: "Es.: principalmente cibi facilmente digeribili, pasti più leggeri prima delle esibizioni", de: "Z. B.: hauptsächlich leicht verdauliche Speisen, vor Auftritten weniger essen", fr: "Ex. : principalement des aliments faciles à digérer, repas plus légers avant les représentations", es: "Ej.: principalmente alimentos fáciles de digerir, comidas más ligeras antes de actuaciones", ko: "예: 소화가 잘 되는 음식 위주, 공연 전에는 적게", ru: "Например: в основном легко усваиваемая еда, перед выступлением — умеренно" },
  placeholderLocationExample: { ja: "例：ミラノ", en: "e.g. Milan", zh: "例：米兰", it: "Es.: Milano", de: "Z. B.: Mailand", fr: "Ex. : Milan", es: "Ej.: Milán", ko: "예: 밀라노", ru: "Например: Милан" },
