  errorAdviceGeneration: { ja: "アドバイスの生成に失敗しました。", en: "Failed to generate advice.", zh: "生成建议失败。", it: "Generazione dei consigli non riuscita.", de: "Ratschlag konnte nicht erstellt werden.", fr: "Échec de la génération du conseil.", es: "Error al generar el consejo.", ko: "조언 생성에 실패했습니다.", ru: "Не удалось сгенерировать совет." },

  caringMsg1: { ja: "今日も記録、お疲れさまでした", en: "Thanks for logging today", zh: "今天也辛苦记录啦", it: "Grazie per aver registrato oggi", de: "Danke fürs Erfassen heute", fr: "Merci d'avoir enregistré aujourd'hui", es: "Gracias por registrar hoy", ko: "오늘도 기록하시느라 수고하셨어요", ru: "Спасибо за сегодняшнюю запись" },
  caringMsg2: { ja: "無理せず、自分のペースで大丈夫です", en: "No need to push — your own pace is just fine", zh: "不必勉强，按自己的节奏就好", it: "Non forzarti, va bene andare al tuo ritmo", de: "Kein Druck – dein eigenes Tempo reicht völlig", fr: "Pas de pression, votre propre rythme suffit", es: "No te fuerces, tu propio ritmo está bien", ko: "무리하지 않아도, 자신의 속도면 충분해요", ru: "Не нужно себя заставлять — ваш собственный темп вполне подходит" },
  caringMsg3: { ja: "声も心も、大切にしてくださいね", en: "Take care of both your voice and your heart", zh: "请好好呵护你的声音与心情", it: "Prenditi cura sia della voce che del cuore", de: "Achte gut auf deine Stimme und dein Herz", fr: "Prenez soin de votre voix et de votre cœur", es: "Cuida tanto tu voz como tu corazón", ko: "목소리도 마음도 소중히 여겨주세요", ru: "Берегите и голос, и душу" },
  caringMsg4: { ja: "今日という日を、ちゃんと見つめられましたね", en: "You took a real, honest look at today", zh: "你好好地正视了今天这一天", it: "Hai guardato con attenzione la giornata di oggi", de: "Du hast dir den heutigen Tag bewusst angesehen", fr: "Vous avez vraiment pris le temps de regarder votre journée", es: "Le prestaste verdadera atención al día de hoy", ko: "오늘 하루를 제대로 들여다보셨네요", ru: "Вы по-настоящему всмотрелись в сегодняшний день" },
  caringMsg5: { ja: "小さな積み重ねが、きっと力になります", en: "These small steps will surely add up to strength", zh: "点滴的积累，一定会成为你的力量", it: "Questi piccoli passi diventeranno sicuramente forza", de: "Diese kleinen Schritte werden bestimmt zu Kraft", fr: "Ces petits pas deviendront sûrement une force", es: "Estos pequeños pasos sin duda se convertirán en fuerza", ko: "작은 쌓임이 분명 힘이 될 거예요", ru: "Маленькие шаги обязательно превратятся в силу" },
  caringMsg6: { ja: "今日もよく頑張りました", en: "You did well today", zh: "今天也很努力了", it: "Hai fatto del tuo meglio anche oggi", de: "Du hast heute gut gearbeitet", fr: "Vous avez bien travaillé aujourd'hui", es: "Lo hiciste bien hoy", ko: "오늘도 잘 해내셨어요", ru: "Сегодня вы хорошо потрудились" },
  caringMsg7: { ja: "ゆっくり休んで、また明日", en: "Rest well, and see you tomorrow", zh: "好好休息，明天见", it: "Riposa bene, a domani", de: "Ruh dich gut aus, bis morgen", fr: "Reposez-vous bien, à demain", es: "Descansa bien, hasta mañana", ko: "푹 쉬고, 내일 또 만나요", ru: "Отдохните как следует, до завтра" },
  caringMsg8: { ja: "自分を労わる時間、大事にしてくださいね", en: "Cherish this time you give yourself", zh: "请珍惜这段善待自己的时间", it: "Custodisci questo tempo che ti dedichi", de: "Schätze diese Zeit für dich selbst", fr: "Chérissez ce temps que vous vous accordez", es: "Valora este tiempo que te dedicas a ti mismo", ko: "자신을 돌보는 시간, 소중히 여겨주세요", ru: "Цените это время, которое вы уделяете себе" },
  caringMsg9: { ja: "続けているあなたを、ちゃんと見ています", en: "We see how consistently you've been showing up", zh: "我们看到了坚持至今的你", it: "Vediamo la tua costanza nel continuare", de: "Wir sehen, wie beständig du dranbleibst", fr: "Nous voyons votre régularité", es: "Vemos tu constancia al seguir así", ko: "꾸준히 이어가고 있는 당신을 지켜보고 있어요", ru: "Мы видим, как стабильно вы продолжаете" },
  caringMsg10: { ja: "記録、ありがとうございます", en: "Thank you for recording today", zh: "感谢你的记录", it: "Grazie per la registrazione", de: "Danke für deinen Eintrag", fr: "Merci pour cet enregistrement", es: "Gracias por tu registro", ko: "기록해 주셔서 감사해요", ru: "Спасибо за запись" },
  labelUnitAvailable: { ja: "あり", en: " available", zh: "可选", it: " disponibile", de: " verfügbar", fr: " disponible", es: " disponible", ko: " 가능", ru: " доступно" },
