  labelShop: { ja: "ショップ", en: "Shop", zh: "商店", it: "Negozio", de: "Shop", fr: "Boutique", es: "Tienda", ko: "상점", ru: "Магазин" },
  labelPlaced: { ja: "設置ずみ", en: "Placed", zh: "已放置", it: "Posizionato", de: "Platziert", fr: "Placé", es: "Colocado", ko: "배치됨", ru: "Размещено" },
  labelEquipped: { ja: "装備中", en: "Equipped", zh: "已装备", it: "Indossato", de: "Ausgerüstet", fr: "Équipé", es: "Equipado", ko: "장착 중", ru: "Надето" },
  btnEquip: { ja: "装備する", en: "Equip", zh: "装备", it: "Indossa", de: "Ausrüsten", fr: "Équiper", es: "Equipar", ko: "장착하기", ru: "Надеть" },
  btnBuy: { ja: "購入", en: "Buy", zh: "购买", it: "Acquista", de: "Kaufen", fr: "Acheter", es: "Comprar", ko: "구매", ru: "Купить" },
  noteSingleSlot: { ja: "同じ種類は1つだけ装備できます。ボタンを押すと切り替わります。", en: "You can equip only one of this kind at a time. Tap to switch.", zh: "同一类型只能装备一件，点击即可切换。", it: "Puoi indossare solo un elemento di questo tipo alla volta. Tocca per cambiare.", de: "Von dieser Art kannst du jeweils nur eins tragen. Zum Wechseln antippen.", fr: "Vous ne pouvez équiper qu'un seul élément de ce type à la fois. Appuyez pour changer.", es: "Solo puedes equipar uno de este tipo a la vez. Toca para cambiar.", ko: "같은 종류는 하나만 장착할 수 있습니다. 눌러서 전환하세요.", ru: "Можно надеть только один предмет этого типа одновременно. Нажмите, чтобы сменить." },

