  gateNeedDays: { ja: "あと{n}日の記録で、{label}が始まります", en: "{label} will begin after {n} more days of records", zh: "再记录{n}天，{label}就会开始", it: "{label} inizierà dopo altri {n} giorni di registrazioni", de: "{label} beginnt nach {n} weiteren Tagen mit Einträgen", fr: "{label} démarrera après {n} jours d'enregistrements supplémentaires", es: "{label} comenzará tras {n} días más de registros", ko: "{n}일 더 기록하면 {label}이(가) 시작됩니다", ru: "{label} начнётся ещё через {n} дн. записей" },
